/**
 * Runs the election described by `candidates` (an array of names) and
 * `ballots` (an array of { count, names }). Returns
 * { rounds, winner } where each round is
 * { votes: [[name, count], ...] (all continuing candidates, in candidate
 * declaration order), exhausted, eliminated (name or null) } and winner is
 * the winning name or null.
 */
export function runElection(candidates, ballots) {
  let continuing = candidates.slice()
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const stillContinuing = new Set(continuing)
    const tally = new Map()
    for (const name of continuing) tally.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => stillContinuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        tally.set(choice, tally.get(choice) + ballot.count)
      }
    }

    history.push(tally)

    const activeTotal = continuing.reduce((sum, name) => sum + tally.get(name), 0)

    const votes = continuing
      .map((name) => [name, tally.get(name)])
      .sort((a, b) => (b[1] - a[1]) || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = null
      break
    }

    const majorityWinner = continuing.find((name) => tally.get(name) * 2 > activeTotal)
    if (majorityWinner !== undefined) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = majorityWinner
      break
    }

    let min = Infinity
    for (const name of continuing) {
      const v = tally.get(name)
      if (v < min) min = v
    }
    let tied = continuing.filter((name) => tally.get(name) === min)
    if (tied.length > 1) {
      tied = breakTie(tied, history)
    }
    const eliminated = tied[0]

    rounds.push({ votes, exhausted, eliminated })

    continuing = continuing.filter((name) => name !== eliminated)
  }

  return { rounds, winner }
}

